// Reads the Idempotency-Key header (fallback: body.submissionId — the sender
// sets both to the same UUID v4). Dedup only applies when the key looks like a
// UUID v4; a missing/malformed key means "process normally, no dedup".
const item = $input.first().json;
const headers = item.headers || {};
const raw = headers['idempotency-key'] || (item.body || {}).submissionId || '';
const key = String(raw).trim().toLowerCase();
const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(key);
return [{ json: Object.assign({}, item, { idempotencyKey: isUuid ? key : '', hasIdempotencyKey: isUuid }) }];

// Data table nodes replace $json with the table row; downstream nodes expect
// the original webhook payload shape.
return [{ json: $('Extract Idempotency Key').first().json }];

// Parse the primary classifier. Sets `failed` so the workflow can try the
// fallback model before giving up. Does NOT fail open here — that only happens
// after the fallback also fails (see Parse Spam Verdict (Fallback)).
const item = $input.first().json;
let spam = false;
let failed = false;
let reason = 'classifier unavailable';
try {
  const out = item.output || {};
  if (item.error !== undefined || out.spam === undefined) {
    failed = true;
  } else {
    spam = out.spam === true || String(out.spam).toLowerCase().trim() === 'true';
    if (out.reason !== undefined) reason = String(out.reason);
  }
} catch (e) { failed = true; }
return [{ json: { spam, reason, failed } }];

