// Terminal parse for the fallback classifier. If this also failed, fail OPEN
// (treat as NOT spam) so a legitimate lead is never silently dropped.
const item = $input.first().json;
let spam = false;
let reason = 'classifier unavailable (primary + fallback) - failed open';
try {
  const out = item.output || {};
  if (item.error === undefined && out.spam !== undefined) {
    spam = out.spam === true || String(out.spam).toLowerCase().trim() === 'true';
    if (out.reason !== undefined) reason = String(out.reason) + ' (fallback model)';
  }
} catch (e) { /* fail open */ }
return [{ json: { spam, reason, failed: false } }];

