// Zendesk search does NOT support querying organizations by domain
// (verified empirically: 'type:organization domain:...' always returns 0),
// so we list all orgs (paginated) and match domain_names client-side.
const domain = ($('Prepare Data').first().json.emailDomain || '').toLowerCase();
const orgs = $input.all().flatMap(i => (i.json.organizations || []));
const match = domain ? orgs.find(o => (o.domain_names || []).some(d => d.toLowerCase() === domain)) : null;
return [{ json: { matched: !!match, orgId: match ? match.id : null, orgName: match ? match.name : '', orgsScanned: orgs.length } }];

